let reportPeriod=7,user=null,data={products:[],sales:[],sale_items:[],expenses:[],stock_log:[],activity:[],suppliers:[],purchases:[],purchase_items:[],supplier_payments:[],cash_closings:[],sale_returns:[],sale_return_items:[],stock_counts:[],settings:{shop_name:'Ilmek',low_stock_default:5,default_theme:'sage'}},usdTry=0,rateDate='',rateDay='',rateStale=false,page='home',cart=[],query='',rateTimer=null,saleSending=false;
const $=s=>document.querySelector(s), tlRound=n=>Math.floor((n||0)+Number.EPSILON*Math.abs(n||0)+0.5), fmt=n=>new Intl.NumberFormat('tr-TR',{maximumFractionDigits:0}).format(tlRound(n))+' ₺', dec=n=>new Intl.NumberFormat('tr-TR',{maximumFractionDigits:2}).format(n||0), dec4=n=>new Intl.NumberFormat('tr-TR',{maximumFractionDigits:4}).format(n||0), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const now=new Date(), asDate=d=>d instanceof Date?d:(typeof d==='string'&&/^\d{4}-\d\d-\d\d \d\d:/.test(d)?new Date(d.replace(' ','T')+'Z'):new Date(d)), datekey=d=>asDate(d).toLocaleDateString('sv-SE'), todaykey=datekey(now), shortdate=d=>asDate(d).toLocaleDateString('tr-TR',{day:'numeric',month:'short'}), timestamp=d=>asDate(d);
function toast(s){let t=$('#toast');t.textContent=s;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2500)}
async function api(path,body){const opt={credentials:'same-origin',headers:{'Content-Type':'application/json'}};if(body!==undefined){opt.method='POST';opt.body=JSON.stringify(body)}let r=await fetch(path,opt),o=await r.json();if(!r.ok){if(r.status===401&&user)logout();throw Error(o.error||'Bir sorun oluştu')}return o}
async function load(){try{data=await api('/api/data');if(data.settings){reportPeriod=Number(data.settings.report_period)||7;if(!localStorage.getItem('ilmek-theme'))applyTheme(data.settings.default_theme)}if(data.settings?.shop_name)document.querySelectorAll('.brand b').forEach(x=>x.textContent=data.settings.shop_name);render()}catch(e){toast(e.message)}}
function setRate(x){let changed=usdTry!==(x.value||0)||rateDay!==(x.snapshot_day||'')||rateStale!==!!x.stale,pay=$('#pay')?.value;usdTry=x.value||0;rateDate=x.date||'';rateDay=x.snapshot_day||'';rateStale=!!x.stale;$('#rate').textContent=usdTry?dec4(usdTry):'—';$('#rateDate').textContent=usdTry?(x.stale?'Yedek kur':'TCMB satış · sabit')+' · '+(rateDate||'tarih yok'): 'Kur alınamadı';$('#rateDate').title=(x.source||'TCMB USD Döviz satış')+' · alışveriş günü '+rateDay;$('#rateDate').style.color=x.stale?'#bd7548':'';if(changed){render();if(pay&&$('#pay'))$('#pay').value=pay}}
async function getRate(){try{let x=await (await fetch('/api/rate',{cache:'no-store'})).json();setRate(x);return x}catch{return null}}
async function start(){ $('#today').textContent=now.toLocaleDateString('tr-TR',{weekday:'long',day:'numeric',month:'long',year:'numeric'});try{let b=await (await fetch('/api/bootstrap')).json();if(b.needs_setup){showSetup(b.requires_setup_token);return}let m=await fetch('/api/me',{credentials:'same-origin'});if(m.ok){user=(await m.json()).user;enter()}else showLogin()}catch{showLogin()} }
function showLogin(){user=null;$('#login').classList.remove('hidden');$('#app').classList.add('hidden');$('.loginbox').innerHTML=`<div class="brandicon">✿</div><div class="eyebrow">AİLE DÜKKÂNIMIZ</div><h1>İlmek</h1><p>Hesabınızla giriş yapın</p><form id="loginForm"><label>Kullanıcı adı<input id="username" autocomplete="username" required></label><label>Parola<input id="password" type="password" autocomplete="current-password" required></label><button class="primary full">Panele gir <span>→</span></button></form>`;$('#loginForm').onsubmit=async e=>{e.preventDefault();try{let o=await api('/api/login',{username:$('#username').value,password:$('#password').value});user=o.user;enter()}catch(err){toast(err.message)}}}
function showSetup(requiresToken=false){$('#login').classList.remove('hidden');$('#app').classList.add('hidden');$('.loginbox').innerHTML=`<div class="brandicon">✿</div><div class="eyebrow">İLK KURULUM</div><h1>Yönetici hesabı</h1><p>Dükkânın sahibi için güvenli bir hesap oluşturalım.</p><form id="setupForm">${requiresToken?'<label>Tek kullanımlık kurulum anahtarı<input id="setupToken" type="password" autocomplete="off" required></label>':''}<label>Adınız<input id="ownerName" autocomplete="name" required></label><label>Kullanıcı adı<input id="ownerUser" autocomplete="username" minlength="3" required></label><label>Parola <small>(en az 10 karakter)</small><input id="ownerPass" type="password" autocomplete="new-password" minlength="10" required></label><button class="primary full">Yönetici hesabını oluştur <span>→</span></button></form>`;$('#setupForm').onsubmit=async e=>{e.preventDefault();try{let o=await api('/api/setup-admin',{name:$('#ownerName').value,username:$('#ownerUser').value,password:$('#ownerPass').value,setup_token:$('#setupToken')?.value||''});user=o.user;enter()}catch(err){toast(err.message)}}}
function enter(){$('#login').classList.add('hidden');$('#app').classList.remove('hidden');document.querySelector('.home-shortcut')?.remove();$('#signedName').textContent=user.name;document.querySelectorAll('.admin-only').forEach(x=>x.classList.toggle('hidden',user.role!=='admin'));document.querySelectorAll('.change-password').forEach(x=>x.remove());let requested=location.hash.match(/^#\/(home|sales|stock|reports|staff|settings)$/)?.[1]||'home';page=requested;if(user.role!=='admin'&&['reports','staff'].includes(page))page='home';document.querySelectorAll('.nav').forEach(x=>x.classList.toggle('active',x.dataset.page===page));if(location.hash!=='#/'+page)history.replaceState({page},'',location.pathname+location.search+'#/'+page);load();getRate();clearInterval(rateTimer);rateTimer=setInterval(()=>{if(user)getRate()},5*60*1000)}
function changePassword(){modal('Kendi parolanızı değiştirin',`<label>Mevcut parola<input id="oldpass" type="password" autocomplete="current-password"></label><label>Yeni parola <small>(en az 10 karakter)</small><input id="newpass" type="password" minlength="10" autocomplete="new-password"></label>`,async()=>{await api('/api/password',{current:$('#oldpass').value,password:$('#newpass').value});user=null;closeModal();showLogin();toast('Parolanız değişti; yeni parola ile tekrar giriş yapın')})}
async function logout(){try{await api('/api/logout')}catch{}user=null;page='home';history.replaceState({page:'home'},'',location.pathname+location.search+'#/home');showLogin()}
document.addEventListener('click',e=>{if(e.target.closest('[data-logout]'))logout()});
document.querySelectorAll('.nav').forEach(b=>b.addEventListener('click',()=>go(b.dataset.page)));
function go(p,fromHistory=false){if(user?.role!=='admin'&&['reports','staff'].includes(p))p='home';if(!['home','sales','stock','reports','staff','settings'].includes(p))p='home';page=p;cart=[];let back=document.querySelector('.home-shortcut');if(p==='home')back?.remove();else if(!back)$('#title').insertAdjacentHTML('beforebegin','<button class="home-shortcut secondary" onclick="go(\'home\')">Ana menu</button>');document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b.dataset.page===p));if(!fromHistory&&location.hash!=='#/'+p)history.pushState({page:p},'',location.pathname+location.search+'#/'+p);render()}
window.addEventListener('popstate',()=>{if(user){let p=location.hash.replace(/^#\//,'')||'home';go(p,true)}});
function paymentBreakdown(){return ['Nakit','Kart','IBAN'].map(m=>[m,data.sales.filter(x=>x.status!=='cancelled'&&x.payment===m&&datekey(x.created)===todaykey).reduce((a,x)=>a+Math.max(0,x.total-(x.return_total||0)),0)])}
function productName(p){return p?.variant?p.name+' · '+p.variant:(p?.name||'')}
function returnedQty(item){return Number(item.returned_qty||0)}
function profits(){let active=data.sales.filter(s=>s.status!=='cancelled'),returnByItem={};data.sale_return_items.forEach(r=>returnByItem[r.sale_item_id]=(returnByItem[r.sale_item_id]||0)+r.qty);let cost=0;data.sale_items.forEach(i=>{if(active.some(s=>s.id===i.sale_id))cost+=Math.max(0,i.qty-(returnByItem[i.id]||0))*(i.unit_cost||0)});let revenue=active.reduce((sum,s)=>sum+Math.max(0,s.total-(s.return_total||0)),0),expense=data.expenses.reduce((sum,x)=>sum+x.amount,0);return {gross:revenue-cost,expense,net:revenue-cost-expense}}
function home(){let salesToday=data.sales.filter(s=>s.status!=='cancelled'&&datekey(s.created)===todaykey),total=salesToday.reduce((a,b)=>a+Math.max(0,b.total-(b.return_total||0)),0),units=data.sale_items.filter(i=>data.sales.find(s=>s.id===i.sale_id&&s.status!=='cancelled'&&datekey(s.created)===todaykey)).reduce((a,b)=>a+Math.max(0,b.qty-returnedQty(b)),0),low=data.products.filter(p=>p.stock<=p.low_stock),pr=profits();let labels=[];for(let n=6;n>=0;n--){let d=new Date();d.setDate(d.getDate()-n);let key=datekey(d);labels.push({key,label:d.toLocaleDateString('tr-TR',{weekday:'short'}),value:data.sales.filter(s=>s.status!=='cancelled'&&datekey(s.created)===key).reduce((a,b)=>a+Math.max(0,b.total-(b.return_total||0)),0)})}let max=Math.max(...labels.map(x=>x.value),1),recent=data.sales.slice(0,5);$('#title').textContent='Günaydın ☀️';$('#content').innerHTML=`<p class="welcome">Dükkânınızın bugünkü durumu burada.</p><section class="employee-actions admin-actions"><button class="action-tile sell" onclick="go('sales')"><span>\u{1F6CD}</span><b>Sat\u0131\u015F yap</b><small>Kasaya gec</small></button><button class="action-tile" onclick="openProduct()"><span>\u{1F4E6}</span><b>\u00DCr\u00FCn ekle</b><small>Stok ve fiyatlari duzenle</small></button><button class="action-tile" onclick="openExpense()"><span>\u{1F4B8}</span><b>Gider ekle</b><small>Dukkan masrafi</small></button><button class="action-tile" onclick="openCashClose()"><span>\u{1F9FE}</span><b>G\u00FCn sonu kasasi</b><small>Nakit, kart ve IBAN sayimi</small></button><button class="action-tile" onclick="go('reports')"><span>\u{1F4CA}</span><b>Raporlar</b><small>Ciro, kar ve satis gecmisi</small></button><button class="action-tile" onclick="go('staff')"><span>\u{1F465}</span><b>Calisan hesaplari</b><small>Yetki ve parola yonetimi</small></button><button class="action-tile" onclick="go('stock')"><span>\u{1F50E}</span><b>\u00DCr\u00FCnleri bul</b><small>Stok ve fiyat duzenleme</small></button></section><section class="grid stats"><div class="card"><div class="statlabel">Bugünkü satış <i>↗</i></div><div class="statvalue">${fmt(total)}</div><div class="sub">${salesToday.length} işlem · ${units} ürün</div></div><div class="card"><div class="statlabel">Bugünkü tahmini kâr <i>✳</i></div><div class="statvalue">${fmt(salesToday.reduce((a,s)=>a+Math.max(0,s.total-(s.return_total||0)),0)-data.sale_items.filter(i=>data.sales.find(s=>s.id===i.sale_id&&s.status!=='cancelled'&&datekey(s.created)===todaykey)).reduce((a,i)=>a+Math.max(0,i.qty-returnedQty(i))*i.unit_cost,0))}</div><div class="sub">Satış tutarı − ürün alış maliyeti</div></div><div class="card"><div class="statlabel">Stokta ürün çeşidi <i>▦</i></div><div class="statvalue">${data.products.length}</div><div class="sub">Toplam ${fmt(data.products.reduce((a,p)=>a+p.stock,0))} adet ürün</div></div><div class="card"><div class="statlabel">Genel tahmini net <i>◷</i></div><div class="statvalue">${fmt(pr.net)}</div><div class="sub">Kayıtlı satışlar − alış maliyetleri − giderler</div></div></section><section class="grid two"><div class="card"><div class="sectionhead"><h2>Son 7 gün satışları</h2><button class="textbtn" onclick="go('reports')">Tüm kayıtlar →</button></div><div class="chart">${labels.map(x=>`<div class="barcol"><span class="baramount">${x.value?fmt(x.value)+' TL':''}</span><div class="bar ${x.key===todaykey?'today':''}" style="height:${Math.max(2,x.value/max*74)}%"></div><span class="barlabel">${x.label}</span></div>`).join('')}</div></div><div class="card"><div class="sectionhead"><h2>Bugünkü ödeme dağılımı</h2></div><div class="activity">${paymentBreakdown().map(([m,n])=>`<div class="activityrow"><div class="bubble">${m==='Nakit'?'₺':m==='Kart'?'▣':'↗'}</div><div><b>${m}</b><small>Bugün tahsil edilen</small></div><strong>${fmt(n)}</strong></div>`).join('')}</div></div></section><section class="grid two low-list"><div class="card"><div class="sectionhead"><h2>Son satışlar</h2><button class="textbtn" onclick="go('reports')">Hepsini gör →</button></div>${recent.length?`<div class="activity">${recent.map(s=>`<div class="activityrow"><div class="bubble">＋</div><div><b>${esc(s.payment)} ile satış</b><small>${shortdate(timestamp(s.created))} · ${new Date(timestamp(s.created)).toLocaleTimeString('tr-TR',{hour:'2-digit',minute:'2-digit'})}</small></div><strong>${fmt(Math.max(0,s.total-(s.return_total||0)))}</strong></div>`).join('')}</div>`:'<div class="empty">Henüz satış kaydı yok.</div>'}</div><div class="card"><div class="sectionhead"><h2>Stok azalanlar</h2><button class="textbtn" onclick="go('stock')">Stoklara git →</button></div>${low.length?`<div class="activity">${low.slice(0,5).map(p=>`<div class="activityrow"><div class="bubble" style="background:#fbede6;color:#bd7548">!</div><div><b>${esc(productName(p))}</b><small>${esc(p.category||'Kategorisiz')}</small></div><span class="pill warn">${p.stock} adet</span></div>`).join('')}</div>`:'<div class="empty">Harika, tüm stoklar yeterli görünüyor 🌿</div>'}</div></section>`}
function employeeHome(){let low=data.products.filter(p=>p.stock<=p.low_stock),today=data.sales.filter(s=>s.status!=='cancelled'&&datekey(s.created)===todaykey),units=data.sale_items.filter(i=>today.some(s=>s.id===i.sale_id)).reduce((n,i)=>n+i.qty,0);$('#title').textContent='Merhaba, '+esc(user.name);$('#content').innerHTML=`<p class="welcome">Ne yapmak istersiniz? B\u00FCy\u00FCk d\u00FCgmelerden se\u00E7in.</p><section class="employee-actions"><button class="action-tile sell" onclick="go('sales')"><span>\u{1F6CD}</span><b>Sat\u0131\u015F yap</b><small>\u00DCr\u00FCnleri se\u00E7, \u00F6demeyi al</small></button><button class="action-tile" onclick="openProduct()"><span>\u{1F4E6}</span><b>\u00DCr\u00FCn ekle</b><small>Yeni \u00FCr\u00FCn ve ba\u015Flang\u0131\u00E7 sto\u011Fu</small></button><button class="action-tile" onclick="openStockIn()"><span>\u{1F4E6}</span><b>Stok giri\u015Fi</b><small>Mevcut \u00FCr\u00FCne yeni al\u0131m ekle</small></button><button class="action-tile" onclick="go('stock')"><span>\u{1F50E}</span><b>\u00DCr\u00FCn bul / stok g\u00F6r</b><small>${data.products.length} \u00FCr\u00FCn / ${low.length} azalan stok</small></button><button class="action-tile" onclick="openExpense()"><span>\u{1F4B8}</span><b>Gider ekle</b><small>D\u00FCkkan masraf\u0131n\u0131 kaydet</small></button><button class="action-tile" onclick="openCashClose()"><span>\u{1F9FE}</span><b>G\u00FCn sonu kasas\u0131</b><small>Bug\u00FCnk\u00FC nakit, kart ve IBAN say\u0131m\u0131</small></button></section><section class="grid stats employee-stats"><div class="card"><div class="statlabel">Bug\u00FCnk\u00FC sat\u0131\u015F</div><div class="statvalue">${today.length}</div></div><div class="card"><div class="statlabel">Sat\u0131lan \u00FCr\u00FCn</div><div class="statvalue">${units}</div></div></section>${low.length?`<div class="card low-notice"><h2>Stok azal\u0131yor</h2>${low.slice(0,5).map(p=>`<div class="activityrow"><div class="bubble">!</div><div><b>${esc(productName(p))}</b></div><span class="pill warn">${p.stock} adet</span></div>`).join('')}</div>`:''}`}

function stock(){let ps=data.products.filter(p=>(productName(p)+' '+p.category+' '+(p.barcode||'')).toLocaleLowerCase('tr').includes(query.toLocaleLowerCase('tr')));$('#title').textContent='Ürün ve stoklar';$('#content').innerHTML=`<div class="pagehead"><h2>Dükkân envanteri <span class="pill">${data.products.length} ürün</span></h2><div class="actions"><button class="primary" onclick="openProduct()">＋ Ürün ekle</button></div></div><div class="filterbar"><input placeholder="Ürün ara veya barkod okut…" value="${esc(query)}" onkeydown="stockSearchKey(event)" oninput="query=this.value;stock()"></div><div class="tablewrap"><table><thead><tr><th>ÜRÜN</th><th>KATEGORİ</th><th>STOK</th><th>ALIŞ MALİYETİ · BUGÜN</th><th>SATIŞ FİYATI · BUGÜN</th><th></th></tr></thead><tbody>${ps.map(p=>`<tr><td>${p.image?`<img src="${esc(p.image)}" class="thumb">`:''}<b>${esc(productName(p))}</b></td><td>${esc(p.category||'—')}</td><td><span class="pill ${p.stock<=p.low_stock?'warn':''}">${p.stock} adet</span></td><td>${fmt((p.cost_usd||0)*usdTry)} ${user.role==='admin'?'<small>· $'+dec4(p.cost_usd||0)+'</small>':''}</td><td><b>${fmt(p.price_usd*usdTry)}</b> ${user.role==='admin'?'<small>· $'+dec4(p.price_usd)+'</small>':''}</td><td><button class="textbtn" onclick="openProduct(${p.id})">Düzenle</button> ${user.role==='admin'?`<button class=\"textbtn danger-text\" onclick=\"deleteProduct(${p.id})\">Sil</button>`:''}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">Henüz ürün yok. İlk ürününüzü ekleyin.</td></tr>'}</tbody></table></div><div class="hint" style="margin-top:13px">Etiket fiyatları her gün güncel USD/TRY kuruyla yeniden hesaplanır ve tam TL gösterilir. Satış sırasında o anki TL tutarı kayda geçer.</div>`}
function salesPage(){let visible=data.products.filter(p=>(productName(p)+' '+(p.barcode||'')).toLocaleLowerCase('tr').includes(query.toLocaleLowerCase('tr'))&&p.stock>0);let total=cart.reduce((a,x)=>a+x.qty*tlRound(x.p.price_usd*usdTry),0);$('#title').textContent='Yeni satış';$('#content').innerHTML=`<div class="saleslayout"><div><div class="pagehead"><h2>Ürün seç</h2><span class="pill">${visible.length} ürün</span></div><div class="filterbar"><input placeholder="Ürün ara veya barkod okut…" value="${esc(query)}" onkeydown="saleSearchKey(event)" oninput="query=this.value;salesPage()"></div><div class="productsgrid">${visible.map(p=>`<button class="producttile" onclick="addCart(${p.id})">${p.image?'<img class="productshot" src="'+esc(p.image)+'" alt="" loading="lazy">':''}<b>${esc(productName(p))}</b><span>${p.stock} adet stokta</span><strong>${fmt(p.price_usd*usdTry)}</strong>${user.role==='admin'?'<small class="usd-price">$'+dec4(p.price_usd)+'</small>':''}</button>`).join('')||'<div class="empty">Stokta ürün bulunamadı.</div>'}</div></div><div class="card"><div class="sectionhead"><h2>Satış sepeti</h2><button class="textbtn" onclick="cart=[];salesPage()">Temizle</button></div>${cart.length?cart.map((x,i)=>`<div class="cartrow"><div><b>${esc(productName(x.p))}</b><small>${fmt(x.p.price_usd*usdTry)} / adet</small></div><div class="qty"><button onclick="qty(${i},-1)">−</button><span>${x.qty}</span><button onclick="qty(${i},1)">+</button></div><button class="remove" onclick="cart.splice(${i},1);salesPage()">×</button></div>`).join(''):'<div class="empty">Başlamak için soldan ürün seçin 🌼</div>'}<div class="totalrow"><span>Toplam</span><strong>${fmt(total)}</strong></div><label>Ödeme biçimi<select id="pay" required><option value="" selected disabled>Ödeme türü seçin</option><option value="Nakit">Nakit</option><option value="Kart">Kart</option><option value="IBAN">IBAN</option></select></label><button class="primary full" onclick="finishSale()" ${cart.length?'':'disabled'}>Satışı tamamla <span>→</span></button></div></div>`}
function reports(){let days=[],today=todaykey,periodLabel=reportPeriod===1?'Bugün':reportPeriod===7?'Son 7 gün':'Son 30 gün',start=new Date();start.setDate(start.getDate()-(reportPeriod-1));let periodStart=datekey(start),periodSales=data.sales.filter(s=>s.status!=='cancelled'&&datekey(s.created)>=periodStart&&datekey(s.created)<=today),saleIds=new Set(periodSales.map(s=>s.id)),periodRevenue=periodSales.reduce((a,s)=>a+Math.max(0,s.total-(s.return_total||0)),0),periodCost=data.sale_items.filter(i=>saleIds.has(i.sale_id)).reduce((a,i)=>a+Math.max(0,i.qty-returnedQty(i))*(i.unit_cost||0),0),periodExpense=data.expenses.filter(e=>datekey(e.created)>=periodStart&&datekey(e.created)<=today).reduce((a,e)=>a+(+e.amount||0),0),periodGross=periodRevenue-periodCost,periodNet=periodGross-periodExpense;for(let n=reportPeriod-1;n>=0;n--){let d=new Date();d.setDate(d.getDate()-n);let key=datekey(d),sales=data.sales.filter(x=>x.status!=='cancelled'&&datekey(x.created)===key).reduce((a,x)=>a+Math.max(0,x.total-(x.return_total||0)),0),buy=data.stock_log.filter(x=>['Yeni alım','İlk stok'].includes(x.note)&&Number(x.qty)>0&&datekey(x.created)===key).reduce((a,x)=>a+x.qty*x.unit_cost,0);days.push({label:reportPeriod===1?'Bug\u00FCn':reportPeriod===30?String(d.getDate()).padStart(2,'0'):d.toLocaleDateString('tr-TR',{weekday:'short'}),sales,buy})}let max=Math.max(1,...days.flatMap(x=>[x.sales,x.buy])),trendHtml='<section class="card trend-card"><div class="sectionhead"><h2>Sat\u0131\u015F ve al\u0131\u015F grafi\u011Fi</h2><select aria-label="Period" id="reportPeriod" onchange="reportPeriod=+this.value;reports();document.getElementById(&quot;reportPeriod&quot;).value=reportPeriod"><option value="1">G\u00FCnl\u00FCk</option><option value="7" selected>Haftal\u0131k</option><option value="30">Ayl\u0131k</option></select><div class="trend-legend"><span><i></i>Satış</span><span><i class="legend-buy"></i>Alış</span></div></div><div class="chart trend-chart" style="--chart-count:'+days.length+'">'+days.map(x=>'<div class="barcol"><span class="baramount">'+(x.sales?fmt(x.sales)+' TL':'')+'</span><div class="barpair"><div class="bar today" title="Satış '+fmt(x.sales)+' TL" style="height:'+Math.max(x.sales?3:0,x.sales/max*100)+'%"></div><div class="bar buybar" title="Alış '+fmt(x.buy)+' TL" style="height:'+Math.max(x.buy?3:0,x.buy/max*100)+'%"></div></div><span class="barlabel">'+x.label+'</span></div>').join('')+'</div><div class="trend-note">'+(days.some(x=>x.sales||x.buy)?'Sat\u0131\u015F ve al\u0131\u015F tutarlar\u0131 TL cinsindendir.':'Se\u00E7ilen d\u00F6nemde hen\u00FCz sat\u0131\u015F veya al\u0131\u015F kayd\u0131 yok.')+'</div></section>';$('#title').textContent='Kayıtlar ve raporlar';$('#content').innerHTML=`<div class="pagehead"><h2>İşletme özeti</h2><div class="actions"><button class="secondary" onclick="exportData()">↓ Yedek indir</button><button class="primary" onclick="makeBackup()">⟳ Şimdi yedekle</button><label class="secondary restore-button">Yedek geri yükle<input type="file" accept=".json,.gz,application/json,application/gzip" onchange="restoreBackup(this)" hidden></label></div></div><section class="grid stats"><div class="card"><div class="statlabel">Toplam ciro</div><div class="statvalue">${fmt(periodRevenue)}</div><div class="sub">${periodLabel}</div></div><div class="card"><div class="statlabel">Tahmini brüt kâr</div><div class="statvalue">${fmt(periodGross)}</div><div class="sub">Ciro − ürün alış maliyetleri</div></div><div class="card"><div class="statlabel">Kayıtlı gider</div><div class="statvalue">${fmt(periodExpense)}</div><div class="sub">${periodLabel}</div></div><div class="card"><div class="statlabel">Tahmini net</div><div class="statvalue">${fmt(periodNet)}</div><div class="sub">Brüt kâr − giderler</div></div></section>${trendHtml}<div class="card" style="margin-top:16px"><div class="sectionhead"><h2>Satış geçmişi</h2><span class="pill">${data.sales.length} kayıt</span></div>${data.sales.length?`<div class="tablewrap"><table><thead><tr><th>TARİH</th><th>ÖDEME</th><th>TUTAR</th><th>ÜRÜN</th><th>TAHMİNİ KÂR</th></tr></thead><tbody>${data.sales.map(s=>{let items=data.sale_items.filter(i=>i.sale_id===s.id),cnt=items.reduce((a,i)=>a+Math.max(0,i.qty-returnedQty(i)),0),cost=items.reduce((a,i)=>a+Math.max(0,i.qty-returnedQty(i))*i.unit_cost,0);return `<tr class="${s.status==='cancelled'?'cancelled':''}"><td>${shortdate(timestamp(s.created))} ${new Date(timestamp(s.created)).toLocaleTimeString('tr-TR',{hour:'2-digit',minute:'2-digit'})}</td><td><span class="pill">${esc(s.payment)}</span></td><td><b>${fmt(Math.max(0,s.total-(s.return_total||0)))}</b> ${s.return_total?'<small>İade '+fmt(s.return_total)+'</small>':''} ${s.status==='cancelled'?'<span class="pill warn">İptal</span>':''}</td><td>${cnt} adet</td><td>${fmt(s.total-(s.return_total||0)-cost)}</td></tr>`}).join('')}</tbody></table></div>`:'<div class="empty">Satış kayıtları burada görünecek.</div>'}</div><div class="grid two" style="margin-top:16px"><div class="card"><div class="sectionhead"><h2>Giderler</h2></div>${data.expenses.length?`<div class="activity">${data.expenses.slice(0,15).map(e=>`<div class="activityrow"><div class="bubble" style="background:#fbede6;color:#bd7548">−</div><div><b>${esc(e.title)}</b><small>${esc(e.payment)} · ${shortdate(timestamp(e.created))}</small></div><strong>− ${fmt(e.amount)}</strong></div>`).join('')}</div>`:'<div class="empty">Henüz gider kaydı yok.</div>'}</div><div class="card"><div class="sectionhead"><h2>Ödeme biçimine göre ciro</h2></div><div class="activity">${['Nakit','Kart','IBAN'].map(m=>`<div class="activityrow"><div class="bubble">${m==='Nakit'?'₺':m==='Kart'?'▣':'↗'}</div><div><b>${m}</b><small>${periodLabel}</small></div><strong>${fmt(periodSales.filter(s=>s.payment===m).reduce((a,s)=>a+Math.max(0,s.total-(s.return_total||0)),0))}</strong></div>`).join('')}</div></div></div>${supplierPanel()}${cashClosePanel()}<div class="hint" style="margin-top:15px">Grafik ve raporlar son 100 satış ve gider kaydını kapsar. Yedekler sunucu klasöründe tutulur. İndirilen JSON dosyasını Drive hesabınıza yükleyebilirsiniz.</div>`}
function settingsPage(){let admin=user.role==='admin',x=data.settings||{shop_name:'Ilmek',low_stock_default:5,default_theme:'sage',report_period:7};$('#title').textContent='D\u00FCkkan ayarlar\u0131';$('#content').innerHTML=`<div class="pagehead"><h2>Hesap ve panel ayarlar\u0131</h2></div><div class="settings-grid"><section class="card settings-card"><h3>Ki\u015Fisel tercihler</h3><div class="account-summary"><b>${esc(user.name)}</b><span>${admin?'Y\u00F6netici':'Sat\u0131\u015F eleman\u0131'} hesab\u0131</span></div><label>Bu cihaz\u0131n temas\u0131<select id="settingTheme"><option value="sage">Ada\u00E7ay\u0131</option><option value="ocean">Deniz</option><option value="rose">G\u00FCl</option><option value="plum">Erik</option><option value="sand">Kum</option><option value="night">Gece</option></select></label><p class="settings-help">Tema bu cihazda hemen uygulan\u0131r; y\u00F6netici kaydederse yeni cihazlar i\u00E7in varsay\u0131lan olur.</p><div class="settings-actions"><button class="secondary" onclick="changePassword()">Parolam\u0131 de\u011Fi\u015Ftir</button><button class="secondary danger-text" data-logout>Oturumu kapat</button></div></section>${admin?`<section class="card settings-card"><h3>D\u00FCkkan ve rapor ayarlar\u0131</h3><label>D\u00FCkkan ad\u0131<input id="settingShopName" maxlength="80" value="${esc(x.shop_name||'Ilmek')}" required></label><label>Yeni \u00FCr\u00FCnler i\u00E7in d\u00FC\u015F\u00FCk stok uyar\u0131 e\u015Fi\u011Fi<input id="settingLowStock" type="number" min="0" max="100000" step="1" value="${Number(x.low_stock_default??5)}" required></label><label>Raporlar ilk a\u00E7\u0131ld\u0131\u011F\u0131nda g\u00F6sterilecek d\u00F6nem<select id="settingPeriod"><option value="1">G\u00FCnl\u00FCk</option><option value="7">Haftal\u0131k</option><option value="30">Ayl\u0131k</option></select></label><p class="settings-help">Dolar kuru TCMB'den g\u00FCnl\u00FCk al\u0131n\u0131r; TL fiyatlar tam liraya yuvarlan\u0131r. Sat\u0131\u015Fta \u00F6deme y\u00F6ntemi zorunludur.</p><div class="settings-actions"><button class="primary" id="saveSettings">D\u00FCkkan ayarlar\u0131n\u0131 kaydet</button><button class="secondary" onclick="go('staff')">\u00C7al\u0131\u015Fan hesaplar\u0131</button></div></section>`:''}</div>`;$('#settingTheme').value=localStorage.getItem('ilmek-theme')||x.default_theme||'sage';$('#settingTheme').onchange=e=>applyTheme(e.target.value);if(admin){$('#settingPeriod').value=String(x.report_period||7);$('#saveSettings').onclick=async()=>{let body={shop_name:$('#settingShopName').value.trim(),low_stock_default:+$('#settingLowStock').value,default_theme:$('#settingTheme').value,report_period:+$('#settingPeriod').value};try{let r=await api('/api/settings',body);data.settings=r.settings;reportPeriod=Number(r.settings.report_period)||7;applyTheme(r.settings.default_theme);document.querySelectorAll('.brand b').forEach(el=>el.textContent=r.settings.shop_name);toast('Ayarlar kaydedildi');settingsPage()}catch(e){toast(e.message)}}}$('#reportPeriod').value=String(reportPeriod)}
function render(){if(!user)return;if(page==='settings'){settingsPage();return}if(page==='home')return user.role==='admin'?home():employeeHome();if(page==='reports'&&user.role!=='admin')return home();if(page==='stock'){stock();let actions=$('.pagehead .actions');actions?.insertAdjacentHTML('afterbegin','<button class="secondary" onclick="openStockIn()">Stok girişi</button>');if(user.role==='admin')actions?.insertAdjacentHTML('afterbegin','<button class="secondary" onclick="openStockCount()">Stok sayımı</button><button class="secondary" onclick="openAdjustment()">Stok düzelt</button>');else document.querySelectorAll('.tablewrap th:nth-child(4),.tablewrap td:nth-child(4)').forEach(x=>x.remove());return}if(page==='sales'){salesPage();return}if(page==='reports'){reports();let expenseCard=[...document.querySelectorAll('.grid.two .card')].find(c=>c.querySelector('h2')?.textContent==='Giderler');if(expenseCard)[...expenseCard.querySelectorAll('.activityrow')].forEach((row,i)=>{let e=data.expenses[i];if(!e)return;let edit=document.createElement('button');edit.className='textbtn';edit.textContent='D?zenle';edit.onclick=()=>openExpense(e.id);let del=document.createElement('button');del.className='textbtn danger-text';del.textContent='Sil';del.onclick=()=>deleteExpense(e.id);row.append(edit,del)});let table=$('.tablewrap table');if(table){let th=document.createElement('th');th.textContent='İŞLEM';table.tHead.rows[0].append(th);[...table.tBodies[0].rows].forEach((row,i)=>{let s=data.sales[i],td=document.createElement('td'),small=document.createElement('small');small.textContent=`Kur ${dec(s.exchange_rate)} · ${s.rate_date}`;if(s.exchange_rate)row.cells[0].append(small);if(s.status==='cancelled'){td.textContent='İptal edildi';row.classList.add('cancelled')}else{let b=document.createElement('button');b.className='textbtn';b.textContent='Satışı iptal et';b.onclick=()=>cancelSale(s.id);td.append(b);let ret=document.createElement('button');ret.className='textbtn';ret.textContent='İade';ret.onclick=()=>returnSale(s.id);td.append(document.createTextNode(' '),ret)}row.append(td)})}return}({staff}[page]||home)()}
async function cancelSale(id){if(!confirm('Bu satışı iptal edelim mi? Ürünler stoğa geri eklenecek ve satış rapordan düşecek.'))return;let reason=prompt('İptal nedenini yazın:','Hatalı satış');if(reason===null)return;try{await api('/api/sales/'+id+'/cancel',{reason});await load();toast('Satış iptal edildi, ürünler stoğa döndü')}catch(e){toast(e.message)}}
async function deleteProduct(id){let p=data.products.find(x=>x.id===id);if(!p||!confirm(p.name+' urunu ve mevcut stogu silinsin mi? Satis veya alis gecmisi olan urun silinemez.'))return;try{let r=await fetch('/api/products/'+id,{method:'DELETE',credentials:'same-origin'}),o=await r.json();if(!r.ok)throw Error(o.error||'Delete failed');await load();toast('\u00DCr\u00FCn silindi')}catch(e){toast(e.message)}}
function openAdjustment(){modal('Stok düzeltme',`<label>Ürün<select id="adjp">${data.products.map(p=>`<option value="${p.id}">${esc(p.name)} · stok ${p.stock}</option>`).join('')}</select></label><div class="formrow"><label>Adet farkı<input id="adjq" type="number" step="1" placeholder="Örn. -2 veya 3"></label><label>Açıklama<input id="adjn" placeholder="Sayım farkı / hasarlı ürün"></label></div><div class="hint">Eksi adet stoktan düşer, artı adet ekler. Değişiklik kimin yaptığını belirten hareket kaydına eklenir.</div>`,async()=>{await api('/api/stock-adjustments',{product_id:+$('#adjp').value,qty:+$('#adjq').value,note:$('#adjn').value});await load();toast('Stok düzeltmesi kaydedildi')})}
function openUser(){modal('Yeni hesap',`<label>Çalışanın adı<input id="un" required></label><label>Kullanıcı adı<input id="uu" minlength="3" required></label><label>Hesap türü<select id="ur"><option value="cashier">Satış elemanı</option><option value="admin">Yönetici</option></select></label><label>Geçici parola <small>(en az 10 karakter)</small><input id="up" type="password" minlength="10" required></label><div class="hint">Satış elemanı satış ve stok işlemi yapar. Yönetici kâr, ciro, gider, yedek ve hesap yönetimini de görebilir.</div>`,async()=>{await api('/api/users',{name:$('#un').value,username:$('#uu').value,role:$('#ur').value,password:$('#up').value});await load();staff();toast('Hesap oluşturuldu')})}
async function staff(){
  if(user.role!=='admin')return;
  $('#title').textContent='Çalışan hesapları';
  $('#content').innerHTML=`<div class="pagehead"><h2>Ekibiniz</h2><button class="primary" onclick="openUser()">＋ Hesap ekle</button></div><div class="hint">Satış ve stok işlemleri kullanıcıyla kaydedilir. Kâr, ciro raporları, giderler ve yedekler yöneticiye özeldir.</div><div id="userlist" class="card"><div class="empty">Hesaplar yükleniyor…</div></div><div class="card" style="margin-top:15px"><div class="sectionhead"><h2>Son hareketler</h2><small>Son 100 işlem</small></div>${data.activity?.length?`<div class="activity">${data.activity.map(a=>`<div class="activityrow"><div class="bubble">◷</div><div><b>${esc(a.name||'Hesap kapalı')} · ${esc(a.action)}</b><small>${esc(a.details)} · ${shortdate(a.created)}</small></div></div>`).join('')}</div>`:'<div class="empty">Henüz hareket yok.</div>'}</div>`;
  try{
    let result=await api('/api/users'),table=document.createElement('table'),wrap=document.createElement('div'),thead=document.createElement('thead'),tr=document.createElement('tr');wrap.className='tablewrap';
    ['AD','KULLANICI ADI','ROL','DURUM','HESAP İŞLEMLERİ'].forEach(t=>{let th=document.createElement('th');th.textContent=t;tr.append(th)});thead.append(tr);table.append(thead);let body=document.createElement('tbody');
    for(let x of result.users){let row=document.createElement('tr');for(let v of [x.name,x.username,x.role==='admin'?'Yönetici':'Satış elemanı',x.active?'Etkin':'Kapalı']){let td=document.createElement('td');td.textContent=v;row.append(td)}let actions=document.createElement('td');
      if(x.id!==user.id){let reset=document.createElement('button');reset.className='textbtn';reset.textContent='Parola yenile';reset.onclick=()=>resetUserPassword(x.id);let toggle=document.createElement('button');toggle.className='textbtn';toggle.textContent=x.active?'Hesabı kapat':'Hesabı aç';toggle.onclick=()=>toggleUser(x.id);actions.append(reset,document.createTextNode(' '),toggle)}
      row.append(actions);body.append(row)}
    table.append(body);wrap.append(table);$('#userlist').replaceChildren(wrap)
  }catch(e){toast(e.message)}
}
async function toggleUser(id){if(!confirm('Hesabın durumunu değiştirelim mi? Geçmiş hareketler korunur.'))return;try{await api('/api/users/'+id+'/toggle',{});await load();staff();toast('Hesap durumu güncellendi')}catch(e){toast(e.message)}}
function resetUserPassword(id){modal('Çalışan parolasını yenile',`<label>Yeni geçici parola<input id="newpass" type="password" minlength="10" required></label><div class="hint">Yeni parolayı çalışana güvenli yoldan iletin. Bu işlem çalışanın açık oturumlarını kapatır.</div>`,async()=>{await api('/api/users/'+id+'/password',{password:$('#newpass').value});toast('Parola yenilendi')})}
function saleSearchKey(e){if(e.key!=='Enter')return;let v=e.target.value.trim(),p=data.products.find(x=>x.barcode&&x.barcode.toLocaleLowerCase('tr')===v.toLocaleLowerCase('tr'));if(p){e.preventDefault();if(p.stock>0){query='';addCart(p.id)}else toast('Bu ürünün stoğu yok')}}function stockSearchKey(e){if(e.key!=='Enter')return;let p=data.products.find(x=>x.barcode&&x.barcode.toLocaleLowerCase('tr')===e.target.value.trim().toLocaleLowerCase('tr'));if(p){e.preventDefault();query=productName(p);stock()}}
function addCart(id){let p=data.products.find(x=>x.id===id),x=cart.find(x=>x.p.id===id);if(x){if(x.qty>=p.stock)return toast('Stokta yeterli adet yok');x.qty++}else cart.push({p,qty:1});salesPage()}
function qty(i,d){let x=cart[i];if(d>0&&x.qty>=x.p.stock)return toast('Stokta yeterli adet yok');x.qty+=d;if(x.qty<=0)cart.splice(i,1);salesPage()}
async function finishSale(){if(!cart.length||saleSending)return;let payment=$('#pay')?.value;if(!payment){toast('Satışı tamamlamadan önce ödeme türünü seçin');$('#pay')?.focus();return}saleSending=true;let button=$('.saleslayout .primary');if(button){button.disabled=true;button.textContent='Kaydediliyor…'}try{let fresh=await getRate();if(!fresh?.value)throw Error('Günlük kur alınamadı; satış bekletildi');let result=await api('/api/sales',{payment,rate_day:fresh.snapshot_day,items:cart.map(x=>({product_id:x.p.id,qty:x.qty}))});cart=[];await load();toast('Satış kaydedildi · '+fmt(result.total))}catch(e){toast(e.message)}finally{saleSending=false;if(cart.length&&page==='sales')salesPage()}}
function modal(title,inside,save,button='Kaydet'){let m=$('#modal');m.innerHTML=`<div class="modalbox" role="dialog" aria-modal="true" aria-labelledby="modalTitle"><h2 id="modalTitle">${title}</h2>${inside}<div class="modalfooter"><button class="secondary" onclick="closeModal()">Vazgeç</button><button class="primary" id="modalSave">${button}</button></div></div>`;m.classList.remove('hidden');m.onclick=e=>{e.stopPropagation()};$('#modalSave').onclick=async()=>{let b=$('#modalSave');if(b.disabled)return;b.disabled=true;try{await save();closeModal()}catch(e){toast(e.message)}finally{if(b.isConnected)b.disabled=false}}}
function closeModal(){$('#modal').classList.add('hidden')}
async function photoData(){let f=$('#photoGallery')?.files?.[0];if(!f)return '';let bitmap=null,url='',img=null;try{if('createImageBitmap'in window)try{bitmap=await createImageBitmap(f)}catch{}if(!bitmap){img=new Image();url=URL.createObjectURL(f);await new Promise((ok,no)=>{img.onload=ok;img.onerror=()=>no(new Error('Bu foto\u011Fraf bi\u00E7imi telefonda a\u00E7\u0131lamad\u0131. iPhone icin Kamera > Bi\u00E7imler > En Uyumlu se\u00E7ene\u011Fini se\u00E7in ve tekrar deneyin.'));img.src=url})}let w=bitmap?.width||img?.naturalWidth||img?.width,h=bitmap?.height||img?.naturalHeight||img?.height;if(!w||!h)throw new Error('Foto\u011Fraf okunamad\u0131. JPEG bi\u00E7iminde yeniden deneyin.');let scale=Math.min(1,1200/Math.max(w,h)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(w*scale));canvas.height=Math.max(1,Math.round(h*scale));let ctx=canvas.getContext('2d');if(!ctx)throw new Error('Foto?raf d?n??t?r?lemedi.');ctx.drawImage(bitmap||img,0,0,canvas.width,canvas.height);let blob=await new Promise(ok=>canvas.toBlob(ok,'image/jpeg',.86));if(!blob)blob=await new Promise(ok=>canvas.toBlob(ok,'image/png'));if(!blob)throw new Error('Foto?raf JPEG/PNG bi?imine ?evrilemedi.');return await new Promise((ok,no)=>{let reader=new FileReader();reader.onload=()=>ok(reader.result);reader.onerror=()=>no(new Error('Foto?raf okunamad?.'));reader.readAsDataURL(blob)})}finally{if(bitmap?.close)bitmap.close();if(url)URL.revokeObjectURL(url)}}
function openProduct(id){if(id&&!usdTry){getRate().then(x=>{if(x?.value)openProduct(id);else toast('G\u00FCncel kur alınamadı')});return}let p=id?data.products.find(x=>x.id===id):null;if(id&&!p)return toast('Ürün bulunamadı');let isEdit=!!p,costField=(!isEdit||user.role==='admin')?'<label>Adet alış maliyeti · bugünkü TL<input id="cost" type="number" min="0" step="0.01" required value="'+(isEdit?((p.cost_usd||0)*usdTry).toFixed(2):'0')+'"></label>':'';let inside='<label>Ürün adı<input id="pn" required value="'+esc(p?.name||'')+'"></label><div class="formrow"><label>Barkod · isteğe bağlı<input id="pb" inputmode="numeric" value="'+esc(p?.barcode||'')+'"></label><label>Tedarikçi · isteğe bağlı<input id="supplierName" list="supplierOptions" value="'+esc(p?.supplier_name||'')+'" placeholder="Tedarikçi seçin"><datalist id="supplierOptions">'+data.suppliers.filter(x=>Number(x.active??1)===1).map(x=>'<option value="'+esc(x.name)+'">').join('')+'</datalist></label></div><label>Ürün fotoğrafı · kamera veya galeriden seç<input id="photoGallery" type="file" accept="image/*"></label><div class="formrow"><label>Kateg\u00F6ri<input id="pc" value="'+esc(p?.category||'')+'"></label>'+(isEdit?'<label>Az stok uyarısı eşiği<input id="low" type="number" min="0" value="'+(p.low_stock||5)+'"></label>':'<label>Başlangıç stoğu<input id="ps" type="number" min="0" value="0"></label><div class="formrow"><label>Odenen tutar TL<input id="initialPaid" type="number" min="0" step="1" value="0"></label><label>Payment type<select id="initialPay"><option value="Debt">Borc / sonra odeme</option><option value="Nakit">Nakit</option><option value="Kart">Kart</option><option value="IBAN">IBAN</option></select></label></div>')+'</div><div class="formrow">'+costField+'<label>Adet satış fiyatı · bugünkü TL<input id="price" type="number" min="0" step="1" required value="'+(isEdit?tlRound((p.price_usd||0)*usdTry):10)+'"></label></div><div class="hint">Alış ve satış fiyatı USD karşılığıyla kaydedilir; TL karşılığı güncel kurla hesaplanır. '+(isEdit?'Maliyet değişikliği mevcut stok için yeni maliyet kabul edilir.':'Varyantları ve barkodları ayrı stok olarak ekleyebilirsiniz.')+'</div>'+(isEdit?'':'<label>Az stok uyarısı eşiği<input id="low" type="number" min="0" value="'+Number(data.settings?.low_stock_default??5)+'"></label>');modal(isEdit?'Ürünü düzenle':'Yeni ürün',inside,async()=>{let currentRate=usdTry?{value:usdTry,snapshot_day:rateDay}:await getRate();if(!currentRate?.value)throw Error('G\u00FCncel kur al\u0131namad\u0131');let image=await photoData(),body={name:$('#pn').value,variant:p?.variant||'',barcode:$('#pb').value,category:$('#pc').value,price_tl:+$('#price').value,rate_day:currentRate.snapshot_day,image,supplier_name:$('#supplierName')?.value||'',paid:+($('#initialPaid')?.value||0),payment:$('#initialPay')?.value||'Debt'};if(user.role==='admin')body.cost_tl=+($('#cost')?.value||0);if(isEdit){body.low_stock=+$('#low').value;await api('/api/products/'+p.id,body)}else{body.stock=+$('#ps').value;body.low_stock=+$('#low').value;body.cost=+($('#cost')?.value||0);await api('/api/products',body)}await load();toast(isEdit?'Ürün bilgileri güncellendi':'Ürün eklendi')})}
function openStockIn(id){if(!data.products.length)return openProduct();let options=data.products.map(p=>'<option value="'+p.id+'" '+(p.id===id?'selected':'')+'>'+esc(productName(p))+' · stok '+p.stock+'</option>').join('');let inside='<label>Ürün<select id="si" required>'+options+'</select></label><label>Tedarikçi<input id="supplierName" list="supplierOptions" placeholder="Tedarikçi adı (isteğe bağlı)"><datalist id="supplierOptions">'+data.suppliers.filter(x=>Number(x.active??1)===1).map(x=>'<option value="'+esc(x.name)+'">').join('')+'</datalist></label><div class="formrow"><label>Alınan adet<input id="sq" type="number" min="1" value="1" required></label><label>Adet alış maliyeti · TL<input id="sc" type="number" min="0" step="0.01" required></label></div><div class="formrow"><label>Ödenen tutar · TL<input id="paid" type="number" min="0" step="1" value="0"></label><label>Ödeme türü<select id="purchasePay"><option value="Borç">Borç / sonra ödenecek</option><option value="Nakit">Nakit</option><option value="Kart">Kart</option><option value="IBAN">IBAN</option></select></label></div><label>Not<input id="purchaseNote" placeholder="İrsaliye veya alış notu"></label>';modal('Alış ve stok kaydı',inside,async()=>{let currentRate=usdTry?{value:usdTry,snapshot_day:rateDay}:await getRate();if(!currentRate?.value)throw Error('G\u00FCncel kur al\u0131namad\u0131');await api('/api/purchases',{supplier_name:$('#supplierName').value,items:[{product_id:+$('#si').value,qty:+$('#sq').value,unit_cost:+$('#sc').value}],paid:+$('#paid').value,payment:$('#purchasePay').value,note:$('#purchaseNote').value,rate_day:currentRate.snapshot_day});await load();toast('Alış kaydedildi, stok güncellendi')})}
function openStockCount(){if(user.role!=='admin')return;let rows=data.products.map(p=>'<div class="count-row"><span>'+esc(productName(p))+' <small>· sistemde '+p.stock+'</small></span><input type="number" min="0" step="1" data-count-product="'+p.id+'" value="'+p.stock+'"></div>').join('');modal('Stok sayımı',rows+'<label>Açıklama<input id="countNote" placeholder="Örn. Aylık sayım"></label><div class="hint">Sayımı kaydedince farklar stoğa işlenir ve hareket geçmişine eklenir.</div>',async()=>{let fields=[...document.querySelectorAll('[data-count-product]')];if(fields.some(x=>x.value.trim()===''))throw Error('Tum urunlerin sayim adetlerini girin');let items=fields.map(x=>({product_id:+x.dataset.countProduct,counted:+x.value}));await api('/api/stock-counts',{items,note:$('#countNote').value});await load();toast('Stok sayımı kaydedildi')})}
async function openCashClose(day=''){let x=await api('/api/cash-close'+(day?'?date='+encodeURIComponent(day):'')),e=x.expected,c=x.closing,date=x.date,fieldName={Nakit:'cash',Kart:'card',IBAN:'iban'},fields=['Nakit','Kart','IBAN'].map(k=>'<div class="formrow"><label>'+k+' - beklenen '+fmt(e[k])+' TL<input type="number" min="0" step="1" data-count-pay="'+k+'" placeholder="Ger\u00E7ekte say\u0131lan tutar" value="'+(c?c['counted_'+fieldName[k]]:'')+'" required></label></div>').join(''),actions=c&&user.role==='admin'?'<button class="secondary danger-text" type="button" onclick="deleteCashClose(\''+date+'\')">Bu kapan\u0131\u015F\u0131 sil</button>':'';modal(c?'G\u00FCn sonu kasas\u0131n\u0131 d\u00FCzelt':'G\u00FCn sonu kasa kontrol\u00FC','<div class="hint">Beklenen tutar sat\u0131\u015Flardan; giderler ve tedarik\u00E7i \u00F6demeleri d\u00FC\u015F\u00FClerek hesapland\u0131. '+(c?'\u00D6nceden girilmi\u015F say\u0131m\u0131 d\u00FCzeltiyorsunuz.':'')+'</div>'+fields+'<label>Not<input id="cashNote" value="'+esc(c?.note||'')+'" placeholder="Kasa fark\u0131 a\u00E7\u0131klamas\u0131"></label>'+actions,async()=>{let inputs=[...document.querySelectorAll('[data-count-pay]')];if(inputs.some(x=>x.value.trim()===''))throw Error('Nakit, kart ve IBAN say\u0131lan tutarlar\u0131n\u0131 girin');let counted={};inputs.forEach(x=>counted[x.dataset.countPay]=+x.value);let r=await api('/api/cash-close',{date,counted,note:$('#cashNote').value});await load();toast('Kasa kaydedildi - fark: '+Object.entries(r.difference).map(([k,v])=>k+' '+fmt(v)).join(' / '))},c?'D\u00FCzeltmeyi kaydet':'G\u00FCn\u00FC kapat')}
async function deleteCashClose(day){if(!confirm(day+' tarihli g\u00FCn sonu kasa kayd\u0131 silinsin mi?'))return;try{let r=await fetch('/api/cash-close?date='+encodeURIComponent(day),{method:'DELETE',credentials:'same-origin'}),o=await r.json();if(!r.ok)throw Error(o.error||'Kasa kayd\u0131 silinemedi');closeModal();await load();toast('G\u00FCn sonu kayd\u0131 silindi')}catch(e){toast(e.message)}}
function openSupplier(id){let v=id?data.suppliers.find(x=>x.id===id):null;if(id&&!v)return toast('Tedarik\u00E7i bulunamad\u0131');modal(v?'Tedarik\u00E7iyi d\u00FCzenle':'Tedarik\u00E7i ekle','<label>Tedarik\u00E7i ad\u0131<input id="supplierNewName" required value="'+esc(v?.name||'')+'"></label><label>Telefon<input id="supplierPhone" type="tel" value="'+esc(v?.phone||'')+'"></label><label>Not<input id="supplierNote" value="'+esc(v?.note||'')+'"></label>',async()=>{await api(v?'/api/suppliers/'+v.id:'/api/suppliers',{name:$('#supplierNewName').value,phone:$('#supplierPhone').value,note:$('#supplierNote').value});await load();toast(v?'Tedarik\u00E7i g\u00FCncellendi':'Tedarik\u00E7i kaydedildi')},v?'De\u011Fi\u015Fiklikleri kaydet':'Kaydet')}
function supplierPanel(){let list=(data.suppliers||[]).map(v=>{let purchases=(data.purchases||[]).filter(x=>x.supplier_id===v.id),due=purchases.reduce((a,x)=>a+(+x.total||0)-(+x.paid||0),0)-(data.supplier_payments||[]).filter(x=>x.supplier_id===v.id).reduce((a,x)=>a+(+x.amount||0),0),active=Number(v.active??1)===1;return '<div class="activityrow"><div class="bubble">&#8599;</div><div><b>'+esc(v.name)+'</b><small>'+esc(v.phone||'')+' &middot; '+purchases.length+' al\u0131\u015F'+(active?'':' &middot; Ar\u015Fivde')+'</small></div><strong>Bor\u00E7 '+fmt(due)+'</strong>'+(active?(due>0?'<button class="textbtn" onclick="paySupplier('+v.id+','+due+')">\u00D6deme ekle</button>':'')+'<button class="textbtn" onclick="openSupplier('+v.id+')">D\u00FCzenle</button><button class="textbtn danger-text" onclick="archiveSupplier('+v.id+')">Sil / ar\u015Fivle</button>':'<button class="textbtn" onclick="restoreSupplier('+v.id+')">Geri al</button>')+'</div>'}).join('');return '<section class="card supplier-card"><div class="sectionhead"><h2>Tedarik\u00E7iler ve bor\u00E7lar</h2><button class="secondary" onclick="openSupplier()">+ Tedarik\u00E7i ekle</button></div>'+(list||'<div class="empty">Hen\u00FCz tedarik\u00E7i yok.</div>')+'</section>'}
