function returnSale(id){let saleItems=data.sale_items.filter(x=>x.sale_id===id);let fields=saleItems.map(i=>{let left=i.qty-returnedQty(i);return '<label>'+esc(i.name)+' · kalan '+left+' adet<input type="number" min="0" max="'+left+'" step="1" value="0" data-return-item="'+i.id+'"></label>'}).join('');modal('Ürün iadesi · satış #'+id,fields+'<label>İade nedeni<input id="returnReason" required placeholder="Örn. yanlış ürün"></label><div class="hint">İade adedi stoğa eklenir; ciro ve tahmini kâr güncellenir. İşlem geçmişte kalır.</div>',async()=>{let items=[...document.querySelectorAll('[data-return-item]')].map(x=>({sale_item_id:+x.dataset.returnItem,qty:+x.value})).filter(x=>x.qty>0);if(!items.length)throw Error('İade edilecek en az bir adet girin');await api('/api/sales/'+id+'/return',{items,reason:$('#returnReason').value});await load();toast('İade kaydedildi')})}
async function restoreBackup(input){let file=input.files?.[0];if(!file)return;if(!confirm('Yedeği geri yükleyince mevcut ürün, satış, alış ve rapor verileri yedektekiyle değişecek. Güvenlik yedeği önce alınacak. Devam edilsin mi?')){input.value='';return}try{let text;if(file.name.toLowerCase().endsWith('.gz')){if(!window.DecompressionStream)throw Error('Bu tarayıcı .gz yedeğini açamıyor; JSON yedeğini seçin.');text=await new Response(file.stream().pipeThrough(new DecompressionStream('gzip'))).text()}else text=await file.text();let backup=JSON.parse(text);await api('/api/restore',{backup});await load();toast('Yedek geri yüklendi')}catch(e){toast(e.message||'Yedek yüklenemedi')}finally{input.value=''}}
