const themes={sage:['#3b684e','#e8efe8','#f7f5f0','#fffefa','#252a25','#ecebe4','#858a80'],ocean:['#28647a','#e3f0f4','#eff7f8','#fbffff','#203139','#dce9eb','#70838a'],rose:['#a44f63','#f7e8ec','#fbf1f2','#fffafa','#35272b','#f0dfe3','#8d777d'],plum:['#704d83','#efe8f5','#f6f1f8','#fffaff','#2f2933','#e7deec','#817587'],sand:['#9a6234','#f5eadb','#f8f1e8','#fffdf8','#342d25','#eee2d1','#897d70'],night:['#8fc69e','#294337','#17231e','#202f28','#f1f5f2','#35463d','#b1c0b6']};function applyTheme(name){let t=themes[name]||themes.sage;document.documentElement.dataset.theme=themes[name]?name:'sage';['--green','--soft','--bg','--paper','--ink','--line','--muted'].forEach((v,i)=>document.documentElement.style.setProperty(v,t[i]));let el=$('#themeSelect');if(el)el.value=themes[name]?name:'sage';localStorage.setItem('ilmek-theme',themes[name]?name:'sage')}const themeSelect=$('#themeSelect');if(themeSelect){applyTheme(localStorage.getItem('ilmek-theme')||'sage');themeSelect.onchange=()=>applyTheme(themeSelect.value)}
